INSERT INTO `characters` (`character_id`, `project_id`, `name`, `age`, `role`, `personality`, `goals`, `fears`, `motivations`, `appearance`, `default_wardrobe_id`, `accessories`, `prop_ids`, `voice_characteristics`, `emotional_traits`, `character_arc`, `current_story_status`, `created_at`, `updated_at`) VALUES
('nigerian_mechanic_past_machine__CHAR_001', 'nigerian_mechanic_past_machine', 'Kemi Adeyemi', '24', 'Protagonist / Mechanic', 'Resourceful, observant, guarded, deeply loyal to family', 'Find his missing father and understand why he left.', 'Being abandoned again, losing his family\'s workshop.', 'Guilt over his father\'s disappearance, desire for truth.', '{\"eyes\": \"Dark brown, alert\", \"face\": \"Sharp jawline, high cheekbones\", \"hair\": \"Short cropped fade, natural black\", \"lips\": \"Thin, often pressed firmly\", \"nose\": \"Straight, prominent\", \"skin\": \"Deep brown, lightly weathered\", \"eyebrows\": \"Thick, slightly arched\", \"body_type\": \"Lean, muscular from manual labor\", \"facial_hair\": \"Light stubble\", \"height_build\": \"5\'10, athletic\", \"permanent_features\": [\"Small scar above left eyebrow from a childhood accident\", \"Grease-stained forearms\"]}', NULL, '[\"Worn leather wristwatch\", \"Tool belt\"]', '[]', 'Calm, measured, with a slight Lagos accent', '[\"Patient\", \"Resilient\", \"Secretive\"]', 'From seeking closure through the past to accepting the present and forging his own path.', 'Recently discovered the machine in his father\'s hidden workshop compartment.', '2026-09-25 23:29:24', '2026-09-25 23:29:24'),
('nigerian_mechanic_past_machine__CHAR_002', 'nigerian_mechanic_past_machine', 'Tunde Balogun', '25', 'Support / Workshop Partner', 'Optimistic, pragmatic, openly emotional, loyal', 'Keep the workshop running, support Kemi.', 'Poverty, losing his friend to obsession.', 'Financial stability, brotherhood.', '{\"eyes\": \"Warm brown\", \"face\": \"Rounder, open features\", \"hair\": \"Short afro, neatly trimmed\", \"lips\": \"Full, often smiling\", \"nose\": \"Broad\", \"skin\": \"Medium brown\", \"eyebrows\": \"Soft, straight\", \"body_type\": \"Stocky, sturdy\", \"facial_hair\": \"Clean-shaven\", \"height_build\": \"5\'8, solid\", \"permanent_features\": [\"Freckles across nose bridge\", \"Calloused hands\"]}', NULL, '[\"Canvas backpack\", \"Simple silver chain\"]', '[]', 'Bright, energetic, expressive', '[\"Supportive\", \"Anxious\", \"Grounded\"]', 'Learns to trust Kemi\'s instincts while maintaining his own independence.', 'Unaware of the machine\'s true nature, focuses on daily workshop tasks.', '2026-09-25 23:29:24', '2026-09-25 23:29:24'),
('nigerian_mechanic_past_machine__CHAR_003', 'nigerian_mechanic_past_machine', 'Nneka Okafor', '38', 'Antagonist / Tech Investigator', 'Calculating, intense, morally gray, highly intelligent', 'Secure the machine for corporate research.', 'Irrelevance, failure to prove her theories.', 'Professional ambition, personal connection to the father\'s past work.', '{\"eyes\": \"Hazel, piercing\", \"face\": \"Angular, sharp features\", \"hair\": \"Sleek shoulder-length bob, jet black\", \"lips\": \"Thin, often set in a firm line\", \"nose\": \"Straight, refined\", \"skin\": \"Light brown, smooth\", \"eyebrows\": \"Thin, well-groomed\", \"body_type\": \"Slender, poised\", \"facial_hair\": \"None\", \"height_build\": \"5\'7, athletic\", \"permanent_features\": [\"Silver geometric earrings\", \"Faint tension lines around eyes\"]}', NULL, '[\"Structured leather satchel\", \"Smart glasses\"]', '[]', 'Authoritative, precise, low register', '[\"Determined\", \"Calculating\", \"Hidden vulnerability\"]', 'Shifts from exploitation to understanding the machine\'s human cost.', 'Tracking rumors of the device\'s activation, closing in on the workshop.', '2026-09-25 23:29:24', '2026-09-25 23:29:24');

