INSERT INTO `episode_outline` (`episode_id`, `project_id`, `episode_number`, `title`, `summary`, `character_ids`, `location_ids`, `created_at`, `updated_at`) VALUES
('nigerian_mechanic_past_machine__EP_001', 'nigerian_mechanic_past_machine', 1, 'The Hidden Compartment', 'Kemi renovates the workshop floor and uncovers a sealed compartment containing his father\'s machine. Tunde helps him move it to the basement. Kemi accidentally activates it, seeing a brief, fragmented echo of his father working late at night.', '[\"nigerian_mechanic_past_machine__CHAR_001\", \"nigerian_mechanic_past_machine__CHAR_002\"]', '[\"nigerian_mechanic_past_machine__LOC_001\", \"nigerian_mechanic_past_machine__LOC_002\"]', '2026-09-25 23:29:24', '2026-09-25 23:29:24'),
('nigerian_mechanic_past_machine__EP_002', 'nigerian_mechanic_past_machine', 2, 'Fragments of Truth', 'Kemi experiments with the machine, learning to stabilize echoes. He pieces together clues about his father\'s final days. Nneka arrives at the workshop, claiming to be an academic researcher, and grows suspicious of the basement activity.', '[\"nigerian_mechanic_past_machine__CHAR_001\", \"nigerian_mechanic_past_machine__CHAR_002\", \"nigerian_mechanic_past_machine__CHAR_003\"]', '[\"nigerian_mechanic_past_machine__LOC_001\", \"nigerian_mechanic_past_machine__LOC_002\"]', '2026-09-25 23:29:24', '2026-09-25 23:29:24'),
('nigerian_mechanic_past_machine__EP_003', 'nigerian_mechanic_past_machine', 3, 'The Memory Bleed', 'Nneka forces her way into the basement, revealing she knew Kemi\'s father and that the machine was part of a banned experiment. The machine overloads, causing Kemi to experience memory bleed. Tunde tries to shut it down while Kemi confronts a painful echo of his father\'s final choice.', '[\"nigerian_mechanic_past_machine__CHAR_001\", \"nigerian_mechanic_past_machine__CHAR_002\", \"nigerian_mechanic_past_machine__CHAR_003\"]', '[\"nigerian_mechanic_past_machine__LOC_002\"]', '2026-09-25 23:29:24', '2026-09-25 23:29:24'),
('nigerian_mechanic_past_machine__EP_004', 'nigerian_mechanic_past_machine', 4, 'Echoes Fade', 'Kemi accepts his father\'s sacrifice to protect him. With Nneka\'s reluctant help, he safely powers down the machine using the final echo\'s coordinates. The workshop returns to normal as Kemi chooses to focus on the present, closing the chapter on his father\'s legacy.', '[\"nigerian_mechanic_past_machine__CHAR_001\", \"nigerian_mechanic_past_machine__CHAR_002\", \"nigerian_mechanic_past_machine__CHAR_003\"]', '[\"nigerian_mechanic_past_machine__LOC_001\", \"nigerian_mechanic_past_machine__LOC_002\"]', '2026-09-25 23:29:24', '2026-09-25 23:29:24');

