(59, 'nigerian_mechanic_past_machine', NULL, 'nigerian_mechanic_past_machine__EP_004_SC_02', 'nigerian_mechanic_past_machine__EP_004_SC_02_SH_02', NULL, NULL, NULL, 'shot_image', 'A cinematic close-up over-the-shoulder shot focusing on a high-tech console interface and hands. Nneka Okafor\'s slender hands tap a holographic keyboard while Kemi Adeyemi\'s grease-stained forearms and muscular hands adjust a physical analog dial. Fragmented data streams visualize on glass screens. Kemi\'s deep brown skin and short cropped fade are visible at the edge of frame. Nneka\'s sleek shoulder-length jet black bob and silver geometric earrings catch the light. Amber warning lights pulse alongside cool blue console glow. Photorealistic, detailed textures, shallow depth of field.', 'queued', NULL, '/ai_movies/nigerian_mechanic_past_machine/episodes/EP_004/images/EP_004_SC_02_SH_02.png', NULL, '2026-09-28 10:48:10', '2026-09-28 10:48:10');
