('nigerian_mechanic_past_machine__LOC_001', 'nigerian_mechanic_past_machine', 'Adeyemi Auto Workshop', 'Single-story concrete building, corrugated metal roof, open bay doors, cluttered workbenches, tool racks, car lifts', 'Lagos industrial district, near busy roads', 'Interior/Exterior', 'Daytime to evening, shifts with natural light', 'Tropical, humid, occasional rain', 'Mixed practical lighting: fluorescent overheads, warm desk lamps, natural sunlight through open doors', 'Rust orange, concrete gray, oil black, warm amber', '[]', 'Busy, gritty, lived-in, mechanically noisy', '[\"Central car lift\", \"Hidden compartment under floorboards\", \"Wall of spare parts\"]', '[\"Tool placement shifts logically with use.\", \"Machine is kept hidden until episode 2.\"]', '2026-09-25 23:29:24', '2026-09-25 23:29:24'),
('nigerian_mechanic_past_machine__LOC_002', 'nigerian_mechanic_past_machine', 'Sub-Basement Archive', 'Concrete walls, exposed pipes, reinforced steel door, server racks, analog dials, projection screen', 'Beneath the main workshop', 'Interior', 'Perpetually dim, relies on machine glow and emergency bulbs', 'N/A', 'Cold cyan machine glow, flickering halogen strips, deep shadows', 'Desaturated cyan, steel gray, dark charcoal', '[]', 'Claustrophobic, tense, technologically advanced yet decaying', '[\"Central projection console\", \"Wall of handwritten logs\", \"Heavy blast door\"]', '[\"Machine state degrades visibly over episodes.\", \"Echo projections only occur here.\"]', '2026-09-25 23:29:24', '2026-09-25 23:29:24');

