INSERT INTO `projects` (`project_id`, `title`, `genre`, `subgenre`, `tone`, `target_audience`, `logline`, `premise`, `themes`, `world_rules`, `setting`, `time_period`, `visual_style`, `color_language`, `narrative_pov`, `major_conflicts`, `stakes`, `ending`, `continuity_rules`, `created_at`, `updated_at`) VALUES
('nigerian_mechanic_past_machine', 'Echoes of the Wrench', 'Sci-Fi Drama', 'Magical Realism Mystery', 'Gritty, melancholic, hopeful', 'Adults who enjoy character-driven sci-fi and African cinema', 'A young Nigerian mechanic uncovers his missing father\'s experimental device that projects fragmented memories, forcing him to piece together the truth behind his father\'s disappearance while confronting his own family\'s secrets.', 'In a bustling Lagos workshop, a mechanic finds a strange analog-digital hybrid machine. When activated, it projects holographic echoes of past events. He must navigate these echoes to find his father, uncovering a conspiracy tied to local tech innovators and family betrayal.', '[\"family legacy\", \"truth versus memory\", \"technological responsibility\", \"grief and acceptance\"]', '[\"The machine only projects fragments from locations where the father previously worked.\", \"Echoes are non-interactive and fade after 30 seconds.\", \"Prolonged use causes physical fatigue and memory bleed in the operator.\"]', 'Lagos, Nigeria', 'Present day', 'Gritty realism blended with soft, desaturated holographic overlays. Warm amber tones for the present, cool cyan for the echoes.', 'Amber, rust, and concrete gray for reality; desaturated cyan and silver for memory projections.', 'Third-person limited, centered on the protagonist', '[\"Protagonist versus the machine\'s limitations\", \"Protagonist versus hidden family secrets\", \"Protagonist versus external forces seeking the device\"]', 'Reuniting with his father and uncovering the truth before the machine\'s unstable core collapses, potentially erasing the memories forever.', 'The protagonist accepts his father\'s sacrifice, uses the final echo to secure his family\'s future, and shuts down the machine, choosing to live in the present.', '[\"Character appearances and wardrobes must remain consistent unless explicitly changed.\", \"Echo projections must visually differ from reality via color grading and slight transparency.\", \"The machine\'s physical state degrades slightly with each use.\"]', '2026-09-25 23:29:24', '2026-09-25 23:29:24');

