CREATE TABLE `shots` (
  `shot_id` varchar(64) NOT NULL,
  `scene_id` varchar(64) NOT NULL,
  `shot_type` varchar(100) DEFAULT NULL,
  `framing` varchar(255) DEFAULT NULL,
  `camera_position` varchar(255) DEFAULT NULL,
  `lens` varchar(100) DEFAULT NULL,
  `camera_movement` varchar(255) DEFAULT NULL,
  `character_ids` json DEFAULT NULL,
  `character_action` text,
  `facial_expression` varchar(255) DEFAULT NULL,
  `environment` text,
  `lighting` text,
  `atmosphere` varchar(255) DEFAULT NULL,
  `duration_seconds` int DEFAULT NULL,
  `sound_effects` json DEFAULT NULL,
  `music_direction` text,
  `image_prompt` text,
  `video_prompt` text,
  `negative_prompt` text,
  `continuity_notes` text,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

