INSERT INTO `shot_dialogue` (`id`, `shot_id`, `character_id`, `line`, `line_order`) VALUES
(1, 'nigerian_mechanic_past_machine__EP_001_SC_01_SH_01', 'nigerian_mechanic_past_machine__CHAR_001', 'Come on... just give way.', 0),
(2, 'nigerian_mechanic_past_machine__EP_001_SC_01_SH_02', 'nigerian_mechanic_past_machine__CHAR_001', 'What kind of seal is this? It\'s like stone.', 0),
(3, 'nigerian_mechanic_past_machine__EP_001_SC_01_SH_03', 'nigerian_mechanic_past_machine__CHAR_001', 'Daddy... what did you build down here?', 0),
(4, 'nigerian_mechanic_past_machine__EP_001_SC_01_SH_04', 'nigerian_mechanic_past_machine__CHAR_001', 'This isn\'t for cars... it\'s something else entirely.', 0),
(5, 'nigerian_mechanic_past_machine__EP_001_SC_02_SH_01', 'nigerian_mechanic_past_machine__CHAR_001', 'I pried up the floorboard. Tell me what you see.', 0),
(6, 'nigerian_mechanic_past_machine__EP_001_SC_02_SH_01', 'nigerian_mechanic_past_machine__CHAR_002', 'Looks like someone\'s forgotten transmission... wait, that\'s not cast iron.', 1),
(7, 'nigerian_mechanic_past_machine__EP_001_SC_02_SH_02', 'nigerian_mechanic_past_machine__CHAR_002', 'It\'s solid. Heavier than a diesel block. We can\'t leave it here.', 0),
(8, 'nigerian_mechanic_past_machine__EP_001_SC_02_SH_02', 'nigerian_mechanic_past_machine__CHAR_001', 'I know. Where do we put it?', 1),
(9, 'nigerian_mechanic_past_machine__EP_001_SC_02_SH_03', 'nigerian_mechanic_past_machine__CHAR_002', 'Rollers on the left, canvas tight on the right. On three.', 0),
(10, 'nigerian_mechanic_past_machine__EP_001_SC_02_SH_03', 'nigerian_mechanic_past_machine__CHAR_001', 'Got it. Steady now, don\'t scratch the casing.', 1),
(11, 'nigerian_mechanic_past_machine__EP_001_SC_02_SH_04', 'nigerian_mechanic_past_machine__CHAR_002', 'Sub-basement. Nobody goes down there anyway.', 0),
(12, 'nigerian_mechanic_past_machine__EP_001_SC_02_SH_04', 'nigerian_mechanic_past_machine__CHAR_001', 'Agreed. Let\'s move it before closing time.', 1),
(13, 'nigerian_mechanic_past_machine__EP_001_SC_03_SH_01', 'nigerian_mechanic_past_machine__CHAR_002', 'Slow on the third step, the concrete\'s slick down here.', 0),
(14, 'nigerian_mechanic_past_machine__EP_001_SC_03_SH_02', 'nigerian_mechanic_past_machine__CHAR_001', 'Right against the steel bracing, Tunde. The floor\'s more stable there.', 0),
(15, 'nigerian_mechanic_past_machine__EP_001_SC_03_SH_03', 'nigerian_mechanic_past_machine__CHAR_002', 'Keep it away from the weeping walls. If you plug it in, tap a separate breaker or the damp wiring\'ll trip the whole grid.', 0),
(16, 'nigerian_mechanic_past_machine__EP_001_SC_03_SH_04', 'nigerian_mechanic_past_machine__CHAR_001', 'Alright. Let\'s see what you\'ve been hiding.', 0),
(17, 'nigerian_mechanic_past_machine__EP_001_SC_04_SH_01', 'nigerian_mechanic_past_machine__CHAR_001', 'Just rust and old wiring... probably nothing but scrap.', 0),
(18, 'nigerian_mechanic_past_machine__EP_001_SC_04_SH_02', 'nigerian_mechanic_past_machine__CHAR_001', 'Whoa—!', 0),
(19, 'nigerian_mechanic_past_machine__EP_001_SC_04_SH_03', 'nigerian_mechanic_past_machine__CHAR_001', 'Daddy? How is this possible?', 0),
(20, 'nigerian_mechanic_past_machine__EP_001_SC_04_SH_04', 'nigerian_mechanic_past_machine__CHAR_001', 'Everything you told me... was it just a cover?', 0),
(21, 'nigerian_mechanic_past_machine__EP_002_SC_01_SH_01', 'nigerian_mechanic_past_machine__CHAR_001', 'Alright, Dad. Let\'s see what you were really building down here.', 0),
(22, 'nigerian_mechanic_past_machine__EP_002_SC_01_SH_02', 'nigerian_mechanic_past_machine__CHAR_001', 'Too much voltage... it\'s overloading the sync matrix!', 0),
(23, 'nigerian_mechanic_past_machine__EP_002_SC_01_SH_03', 'nigerian_mechanic_past_machine__CHAR_001', 'Not brute force... it needs rhythm. Sync the torque, match the frequency.', 0),
(24, 'nigerian_mechanic_past_machine__EP_002_SC_01_SH_04', 'nigerian_mechanic_past_machine__CHAR_001', 'Physical sync... it\'s not just code. It\'s a mechanical heartbeat.', 0),
(25, 'nigerian_mechanic_past_machine__EP_002_SC_02_SH_01', 'nigerian_mechanic_past_machine__CHAR_001', 'Coordinates locked. Let\'s see what you really hid.', 0),
(26, 'nigerian_mechanic_past_machine__EP_002_SC_02_SH_02', 'nigerian_mechanic_past_machine__CHAR_001', 'Dad... is that really you?', 0),
(27, 'nigerian_mechanic_past_machine__EP_002_SC_02_SH_03', 'nigerian_mechanic_past_machine__CHAR_001', 'He wasn\'t just working late... he was hiding something.', 0),
(28, 'nigerian_mechanic_past_machine__EP_002_SC_02_SH_04', 'nigerian_mechanic_past_machine__CHAR_001', 'Not just a breakdown. It was a cover-up. I\'ll find the rest.', 0),
(29, 'nigerian_mechanic_past_machine__EP_002_SC_03_SH_01', 'nigerian_mechanic_past_machine__CHAR_003', 'Mr. Adeyemi? I\'m Dr. Nneka Okafor, conducting field research on Lagos\'s industrial heritage. May I ask what vintage equipment runs here?', 0),
(30, 'nigerian_mechanic_past_machine__EP_002_SC_03_SH_02', 'nigerian_mechanic_past_machine__CHAR_003', 'This generator\'s output exceeds standard automotive repair needs. Does it power anything beyond the lifts?', 0),
(31, 'nigerian_mechanic_past_machine__EP_002_SC_03_SH_03', 'nigerian_mechanic_past_machine__CHAR_001', 'It\'s just a repair shop, Doctor. We fix engines, not history books. You\'ll have to excuse me, I\'ve got orders to meet.', 0),
(32, 'nigerian_mechanic_past_machine__EP_002_SC_03_SH_04', 'nigerian_mechanic_past_machine__CHAR_003', 'That frequency... it doesn\'t match any standard generator. What\'s running down there, Mr. Adeyemi?', 0),
(33, 'nigerian_mechanic_past_machine__EP_002_SC_04_SH_01', 'nigerian_mechanic_past_machine__CHAR_003', 'The ventilation schematics don\'t account for that sub-level access. I need to verify the airflow ducts down there.', 0),
(34, 'nigerian_mechanic_past_machine__EP_002_SC_04_SH_01', 'nigerian_mechanic_past_machine__CHAR_001', 'It\'s just old storage. Not safe for structural inspections.', 1),
(35, 'nigerian_mechanic_past_machine__EP_002_SC_04_SH_02', 'nigerian_mechanic_past_machine__CHAR_001', 'We keep decades of unsorted spare parts down there. Dust, heavy crates, poor lighting. I can\'t risk an academic liability claim.', 0),
(36, 'nigerian_mechanic_past_machine__EP_002_SC_04_SH_02', 'nigerian_mechanic_past_machine__CHAR_003', 'Liability isn\'t my concern. Unmapped infrastructure is.', 1),
(37, 'nigerian_mechanic_past_machine__EP_002_SC_04_SH_03', 'nigerian_mechanic_past_machine__CHAR_001', 'Besides, the main breaker for that section trips if you draw too much power. I\'d have to reset the whole workshop grid.', 0),
(38, 'nigerian_mechanic_past_machine__EP_002_SC_04_SH_04', 'nigerian_mechanic_past_machine__CHAR_003', 'Your excuses are as outdated as your engine blocks, Kemi. Open the door.', 0),
(39, 'nigerian_mechanic_past_machine__EP_002_SC_04_SH_04', 'nigerian_mechanic_past_machine__CHAR_001', 'You heard me. It\'s not safe, and I\'m not signing a waiver for your research.', 1),
(40, 'nigerian_mechanic_past_machine__EP_003_SC_01_SH_01', 'nigerian_mechanic_past_machine__CHAR_003', 'Step away from the console. Both of you.', 0),
(41, 'nigerian_mechanic_past_machine__EP_003_SC_01_SH_02', 'nigerian_mechanic_past_machine__CHAR_003', 'I\'m not here to arrest you. I worked with your father on this.', 0),
(42, 'nigerian_mechanic_past_machine__EP_003_SC_01_SH_02', 'nigerian_mechanic_past_machine__CHAR_001', 'That\'s a lie. You\'re just another government tracker.', 1),
(43, 'nigerian_mechanic_past_machine__EP_003_SC_01_SH_03', 'nigerian_mechanic_past_machine__CHAR_002', 'Enough! You\'re scaring him. Back off before things get worse.', 0),
(44, 'nigerian_mechanic_past_machine__EP_003_SC_01_SH_03', 'nigerian_mechanic_past_machine__CHAR_003', 'He needs to know what this machine actually is before it tears this building apart.', 1),
(45, 'nigerian_mechanic_past_machine__EP_003_SC_01_SH_04', 'nigerian_mechanic_past_machine__CHAR_003', 'It\'s not just a machine, Kemi. It\'s a temporal resonance experiment. And it\'s already unstable.', 0),
(46, 'nigerian_mechanic_past_machine__EP_003_SC_01_SH_04', 'nigerian_mechanic_past_machine__CHAR_001', 'My father wouldn\'t let you near this place if he knew what you were really after.', 1),
(47, 'nigerian_mechanic_past_machine__EP_003_SC_02_SH_01', 'nigerian_mechanic_past_machine__CHAR_003', 'They didn\'t just bury it, Kemi. The ethical violations were catastrophic. They shut it down because it tears time apart.', 0),
(48, 'nigerian_mechanic_past_machine__EP_003_SC_02_SH_02', 'nigerian_mechanic_past_machine__CHAR_001', 'My father built this to fix what was broken. You\'re asking me to destroy his life\'s work.', 0),
(49, 'nigerian_mechanic_past_machine__EP_003_SC_02_SH_03', 'nigerian_mechanic_past_machine__CHAR_002', 'The voltage is spiking off the charts. The cores are overheating. It\'s not waiting for us to decide—it\'s failing on its own.', 0),
(50, 'nigerian_mechanic_past_machine__EP_003_SC_02_SH_04', 'nigerian_mechanic_past_machine__CHAR_003', 'Kill it now, Kemi! Before the feedback loop locks in!', 0),
(51, 'nigerian_mechanic_past_machine__EP_003_SC_02_SH_04', 'nigerian_mechanic_past_machine__CHAR_002', 'The structural integrity is dropping! We don\'t have time!', 1),
(52, 'nigerian_mechanic_past_machine__EP_003_SC_04_SH_01', 'nigerian_mechanic_past_machine__CHAR_001', 'Dad... what did you actually do?', 0),
(53, 'nigerian_mechanic_past_machine__EP_003_SC_04_SH_02', 'nigerian_mechanic_past_machine__CHAR_003', 'Kemi, detach now! The resonance is pulling you deeper!', 0),
(54, 'nigerian_mechanic_past_machine__EP_003_SC_04_SH_03', 'nigerian_mechanic_past_machine__CHAR_002', 'The main relay\'s fused! I\'m trying to bypass the secondary grid!', 0),
(55, 'nigerian_mechanic_past_machine__EP_003_SC_04_SH_04', 'nigerian_mechanic_past_machine__CHAR_001', 'You didn\'t leave us... you went back.', 0),
(56, 'nigerian_mechanic_past_machine__EP_004_SC_01_SH_01', 'nigerian_mechanic_past_machine__CHAR_001', 'You didn\'t just build it... you stayed to hold it together.', 0),
(57, 'nigerian_mechanic_past_machine__EP_004_SC_01_SH_02', 'nigerian_mechanic_past_machine__CHAR_003', 'The readings didn\'t lie. But I didn\'t expect to find you standing guard over a ghost.', 0),
(58, 'nigerian_mechanic_past_machine__EP_004_SC_01_SH_03', 'nigerian_mechanic_past_machine__CHAR_001', 'I can\'t isolate the core alone. I need your access codes and your engineering knowledge to bring it down without tearing the timeline apart.', 0),
(59, 'nigerian_mechanic_past_machine__EP_004_SC_01_SH_04', 'nigerian_mechanic_past_machine__CHAR_003', 'If we do this, we do it by the book. One wrong input and we\'re both erased.', 0),
(60, 'nigerian_mechanic_past_machine__EP_004_SC_02_SH_01', 'nigerian_mechanic_past_machine__CHAR_001', 'Dad\'s routing protocols are fragmented, but the base frequency matches your drive.', 0),
(61, 'nigerian_mechanic_past_machine__EP_004_SC_02_SH_01', 'nigerian_mechanic_past_machine__CHAR_003', 'Syncing the log fragments now. If his engineering holds, the isolation matrix should align.', 1),
(62, 'nigerian_mechanic_past_machine__EP_004_SC_02_SH_02', 'nigerian_mechanic_past_machine__CHAR_001', 'The temporal drift is compensating itself. He built in a failsafe.', 0),
(63, 'nigerian_mechanic_past_machine__EP_004_SC_02_SH_02', 'nigerian_mechanic_past_machine__CHAR_003', 'Isolating the final echo coordinates. Locking the matrix in three... two...', 1),
(64, 'nigerian_mechanic_past_machine__EP_004_SC_02_SH_03', 'nigerian_mechanic_past_machine__CHAR_001', 'The core\'s rejecting the isolation sequence!', 0),
(65, 'nigerian_mechanic_past_machine__EP_004_SC_02_SH_03', 'nigerian_mechanic_past_machine__CHAR_003', 'It\'s a feedback loop. Hold the primary valve steady or we lose the lock!', 1),
(66, 'nigerian_mechanic_past_machine__EP_004_SC_02_SH_04', 'nigerian_mechanic_past_machine__CHAR_001', 'Override engaged. The sequence is locked.', 0),
(67, 'nigerian_mechanic_past_machine__EP_004_SC_02_SH_04', 'nigerian_mechanic_past_machine__CHAR_003', 'Countdown active. We have exactly sixty seconds before the cascade hits.', 1),
(68, 'nigerian_mechanic_past_machine__EP_004_SC_03_SH_01', 'nigerian_mechanic_past_machine__CHAR_001', 'The isolation matrix is holding, but the surge is routing straight to the core!', 0),
(69, 'nigerian_mechanic_past_machine__EP_004_SC_03_SH_01', 'nigerian_mechanic_past_machine__CHAR_003', 'Rerouting auxiliary power to the grid. Don\'t let the dials spike past red.', 1),
(70, 'nigerian_mechanic_past_machine__EP_004_SC_03_SH_02', 'nigerian_mechanic_past_machine__CHAR_001', 'I\'m cutting the primary safeties. If this fails, we lose the whole sector.', 0),
(71, 'nigerian_mechanic_past_machine__EP_004_SC_03_SH_02', 'nigerian_mechanic_past_machine__CHAR_003', 'Grid is holding at eighty percent. Do it, Kemi. Now.', 1),
(72, 'nigerian_mechanic_past_machine__EP_004_SC_03_SH_03', 'nigerian_mechanic_past_machine__CHAR_001', 'Rest now, Baba. I\'m bringing you home.', 0),
(73, 'nigerian_mechanic_past_machine__EP_004_SC_03_SH_04', 'nigerian_mechanic_past_machine__CHAR_003', 'Power draw is zero. It\'s... actually done.', 0),
(74, 'nigerian_mechanic_past_machine__EP_004_SC_03_SH_04', 'nigerian_mechanic_past_machine__CHAR_001', 'Yeah. It\'s finally quiet.', 1),
(75, 'nigerian_mechanic_past_machine__EP_004_SC_04_SH_01', 'nigerian_mechanic_past_machine__CHAR_003', 'The readings are flat. It\'s actually over.', 0),
(76, 'nigerian_mechanic_past_machine__EP_004_SC_04_SH_01', 'nigerian_mechanic_past_machine__CHAR_001', 'Yeah. Let\'s get out of here.', 1),
(77, 'nigerian_mechanic_past_machine__EP_004_SC_04_SH_02', 'nigerian_mechanic_past_machine__CHAR_001', 'Smells like oil and rust again. Good.', 0),
(78, 'nigerian_mechanic_past_machine__EP_004_SC_04_SH_03', 'nigerian_mechanic_past_machine__CHAR_002', 'Got that alternator you mentioned last week. You ready to tackle it?', 0),
(79, 'nigerian_mechanic_past_machine__EP_004_SC_04_SH_03', 'nigerian_mechanic_past_machine__CHAR_001', 'Yeah. Let\'s get it running.', 1),
(80, 'nigerian_mechanic_past_machine__EP_004_SC_04_SH_04', 'nigerian_mechanic_past_machine__CHAR_001', 'One bolt at a time. Just like always.', 0),
(81, 'nigerian_mechanic_past_machine__EP_003_SC_03_SH_01', 'nigerian_mechanic_past_machine__CHAR_001', 'It\'s not just power... it\'s syncing to my head!', 0),
(82, 'nigerian_mechanic_past_machine__EP_003_SC_03_SH_02', 'nigerian_mechanic_past_machine__CHAR_002', 'Kemi, step away! I\'m pulling the main breaker!', 0),
(83, 'nigerian_mechanic_past_machine__EP_003_SC_03_SH_03', 'nigerian_mechanic_past_machine__CHAR_003', 'The resonance is locked! I\'m trying to dampen the feedback loop, don\'t fight it!', 0),
(84, 'nigerian_mechanic_past_machine__EP_003_SC_03_SH_04', 'nigerian_mechanic_past_machine__CHAR_001', 'I can\'t... it\'s pulling me under!', 0),
(85, 'nigerian_mechanic_past_machine__EP_003_SC_03_SH_04', 'nigerian_mechanic_past_machine__CHAR_003', 'Override failed! It\'s rewriting the sequence!', 1);

